string MandatArketimi =(string)report.Parameters["parameterlabelRaportMAndatArketimi"].Value;
string MandatPagese =(string)report.Parameters["parameterlabelRaportMandatPagese"].Value;
string Derdhje = report.Parameters["parameterlabelRaportDerdhje"].Value.ToString();
string Terheqje =(string)report.Parameters["parameterlabelRaportTerheqje"].Value;

            if (GetCurrentColumnValue("LLOJIVEPRIMIT") != null)
            {
                if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Arketim")
                    xrTableCell2.Text = MandatArketimi;
                if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Pagese")
                    xrTableCell2.Text = MandatPagese; 
                if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Derdhje")
                    xrTableCell2.Text = Derdhje; 
                if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Terheqje")
                    xrTableCell2.Text = Terheqje; 
            }
        }

