private void xrTableCell14_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
             XRTableCell label = (XRTableCell)sender;
		 XtraReport report = (XtraReport)label.Report;

            if (GetCurrentColumnValue("LLOJIVEPRIMIT") != null && GetCurrentColumnValue("NRSERIALANULLIMI") != null
                    && GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Pagese"
                    && GetCurrentColumnValue("NRSERIALANULLIMI").ToString() != String.Empty
               )
            {
                xrTableCell14.Text = (string)report.Parameters["parameterlabelRaportiAnullimArketimi"].Value + GetCurrentColumnValue("NRSERIALANULLIMI").ToString();
                return;
            }

            string msisdn = "";
            int nrfaturash = 0;
            string muajt = (GetCurrentColumnValue("muaj") != null) ? GetCurrentColumnValue("muaj").ToString() : "";
            string opsioni = ((GetCurrentColumnValue("OpsioniVod") != null) ? GetCurrentColumnValue("OpsioniVod").ToString() : "");

            if (GetCurrentColumnValue("NRFATURASH") != null)
                nrfaturash = Convert.ToInt32(GetCurrentColumnValue("NRFATURASH").ToString());

            if (GetCurrentColumnValue("KODKONFIGAMBJENTE") != null && GetCurrentColumnValue("KODKONFIGAMBJENTE").ToString().StartsWith("BPS") && GetCurrentColumnValue("CUSTOMERNUMBER") != null)
                msisdn = ", " + GetCurrentColumnValue("CUSTOMERNUMBER").ToString();

            if (muajt.Contains("Pa fature")) //heqim nga numerimi rreshtin qe shtohet ne rastin e rrumbullakimeve
                nrfaturash--;

            if (nrfaturash == 0) //do te thote qe ka vetem 1 rresht gjithsej pa fature
            {
                xrTableCell14.Text = "Detyrim i prapambetur" + msisdn;
                return;
            }
            else if(muajt.Contains( "Me te vjetra se nje vit") && nrfaturash == 1)
            {
                xrTableCell14.Text = "Pagese faturash me te vjetra se nje vit" + msisdn;
                return;
            }




            xrTableCell14.Text = opsioni;
        }
